def restore_api_names(source,target):
    """API identifiers are immutable even when a template leaves them outside code."""
    s=html.fragment_fromstring(source,create_parent='div');t=html.fragment_fromstring(target,create_parent='div')
    source_links=s.xpath('.//a');target_links=t.xpath('.//a')
    for a,b in zip(source_links,target_links):
        label=' '.join(a.text_content().split())
        if label in {'Constructors','Methods','Properties','Fields','Events','Operators'} and a.get('href','').rstrip('/').split('/')[-1]==label.lower():continue
        if a.get('href')==b.get('href') and '/docs/api/csharp/' in a.get('href','') and re.fullmatch(r'[A-Z][A-Za-z0-9_]*',label):set_inner(b,inner(a))
    return inner(t)
